"""usage: write_notes.py <plan> <engine hash> <gate commit hash>"""
import sys
P, E, G = sys.argv[1:4]
t = "tests/test_u21_no_overlap.py"
bf = (f" *Note 2026-10-31 (12ab-U21B, R761(c), R762):* U21 landed at `{E}`, the gate's evidence at `{G}`. **N23 CLOSED** by (c)(i): one route, the read timeout, no race. **N24 CLOSED**: every executor is shut down in a `finally`, the post-restart site included. No new request is sent while the previous worker is alive: the engine waits on the same future, bounded by the request's whole httpx budget (`_REQUEST_BOUND`, 990 s), so the read timeout, whose clock starts after connect and write, ends the request. A late response is a completion, recorded 'completed' with its lateness in `outcome_detail`. F7's two re-checks now precede the post-restart send (`check_call_digest`, `check_call_env`), outside the try. The five details of (c)(iv) and R762(c)'s sixth (`worker_alive_at_read_timeout`, no restart, nothing sent) are the closed set `RUN_CALL_ENDING_DETAILS` in `run_manifest.py`; no migration, and R745(d)'s distinct outcome stays 023's. F3 is recorded closed by (c)(i)'s bound; F12 is C47's family, not U21's (R761(c)(v)), stated here and not on C47's row. Acceptance, each failing on the parent `8abaedc2308f5958f9dc4d8825f85ed885d7160d` and passing in the gate (`3490 passed, 17 deselected, 1 xfailed, 2 warnings in 926.81s`): `{t}::test_no_attempt_starts_while_the_previous_request_is_still_running`, `::test_a_late_response_is_used_and_recorded_completed_with_lateness`, `::test_a_slow_request_with_no_retries_does_not_restart`, `::test_a_read_timed_out_request_reaches_the_restart_once_and_the_final_attempt_is_rechecked`, `::test_a_digest_changed_by_the_restart_refuses_the_final_send`, `::test_an_env_drift_after_the_restart_refuses_the_final_send_and_writes_its_record`, `::test_the_post_restart_path_writes_the_env_record`, `::test_outside_a_run_the_env_recheck_writes_nothing_and_says_so`, `::test_the_detail_set_is_the_six_endings`, `::test_the_opt_out_ending_is_recorded`, `::test_the_foreign_lock_ending_is_recorded`, `::test_the_restart_command_ending_is_recorded`, `::test_the_post_restart_ending_is_recorded`, `::test_the_worker_alive_ending_is_recorded_with_no_restart_and_nothing_sent` and `::test_no_executor_outlives_its_call`. Six of those (the detail set and the five ending tests) fail on the parent at a name it lacks, not at a behaviour. Pin, green on the parent by construction: `::test_other_timeout_members_keep_their_retry` (R736(c)). Recorded limits: whether a disconnect the server sees cancels generation (R761(b)); the recovery restart is exercised by fakes only, never against the real server. Wave 1 rows 66 and 93's P7 extensions are not closed by this note; this row's own state is not changed by it. Both pins and the audit prompt_hash byte-identical; no migration. Evidence `12ab_U21B/`. N23 and N24 counted until P1 closes (R607(d)).")
ib = (f" *Note 2026-10-31 (12ab-U21B, R761(c)(iii), R761(c)(v)):* **CLOSED** on U21 (`{E}`). A watchdog timeout no longer reaches the restart: the preflight and the quality check reach it only after their request has ended by the read timeout. `{t}::test_a_slow_request_with_no_retries_does_not_restart` (failed on the parent, passes in the gate) and `::test_a_read_timed_out_request_reaches_the_restart_once_and_the_final_attempt_is_rechecked`. Counted until P1 closes (R607(d)).")
dated = (f"*Dated 2026-10-31 (12ab-U21B, R761, R762):* U21 landed at `{E[:7]}`; INT-ab12-1, N23 and N24 CLOSED on it and counted until P1 closes (R607(d)). P1's fix units 37, done 24 (U01–U21, U37, U38, U39). Rows 281 (94 / 56 / 131, 0 unclassed), by hand until the 12ab closeout's recount (R758(a)); rows out 0.")
L = open(P, encoding="utf-8").read().split("\n")
def note(prefix, text):
    i = [n for n, l in enumerate(L) if l.startswith(prefix)]; assert len(i) == 1, (prefix, i)
    assert L[i[0]].endswith(" |"); L[i[0]] = L[i[0]][:-2] + text + " |"
note("| B-F14 | After a watchdog", bf); note("| INT-ab12-1 | With `max_retries=0`", ib)
a = [n for n, l in enumerate(L) if l.startswith("*Dated 2026-10-30 (12aa-U20C, R744(f)):*")]; assert len(a) == 1
L[a[0] + 1:a[0] + 1] = ["", dated]
open(P, "w", encoding="utf-8").write("\n".join(L))
